package com.luminor.tavernquest.feature.tavern
import androidx.lifecycle.*;import com.luminor.tavernquest.domain.model.*;import com.luminor.tavernquest.domain.repository.*;import com.luminor.tavernquest.domain.rules.LevelCalculator;import com.luminor.tavernquest.domain.usecase.contract.*;import dagger.hilt.android.lifecycle.HiltViewModel;import javax.inject.Inject;import kotlinx.coroutines.flow.*;import kotlinx.coroutines.launch
@HiltViewModel class TavernViewModel @Inject constructor(hero:HeroRepository,tavern:TavernRepository,get:GetDailyBoardUseCase,private val gen:GenerateDailyBoardUseCase,level:LevelCalculator):ViewModel(){val ui=combine(hero.observe(),tavern.observe(),get()){h,t,b->TavernUiState(h,t,b.filter{it.status==ContractStatus.ACCEPTED},h?.let{level.calculate(it.totalXp)})}.stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),TavernUiState());init{viewModelScope.launch{gen()}}}
